import {voiceReference} from './voice-reference-store.js';
export function setupLocalVoice(audio){const $=id=>document.getElementById(id);let runtime,remembered,busy=false;const message=text=>$('local-voice-status').textContent=text;
async function prepare(file,save){if(busy)return;if(!file){message('Selecione a gravação autorizada da voz primeiro.');return}if(file.size>30*1024*1024){message('Use um arquivo de áudio de até 30 MB.');return}busy=true;$('local-voice-prepare').disabled=true;$('local-voice-file').disabled=true;try{if(runtime)audio.clear();audio.setLocalVoice(null);await runtime?.dispose();runtime=null;message('Preparando a voz padrão de todas as falas…');const {prepareLocalVoice}=await import('/voice-runtime/local-voice.js');runtime=await prepareLocalVoice(file,p=>message('Baixando modelo: '+Math.round(p.loaded/1048576)+' MB'+(p.total?' / '+Math.round(p.total/1048576)+' MB':'')));remembered=file;let saved=true;if(save)try{await voiceReference('write',{file,name:file.name||'Voz do amigo'})}catch{saved=false}audio.setLocalVoice(async(text,signal)=>{const start=performance.now();message('Gerando fala com a voz do amigo…');try{const blob=await runtime.say(text,signal);message('Voz padrão pronta · última geração: '+((performance.now()-start)/1000).toFixed(1)+' s.');return blob}catch(error){message('Falha na voz: '+error.message);throw error}});$('local-voice-test').disabled=false;$('local-voice-release').disabled=false;$('local-voice-forget').disabled=false;message('Voz do amigo padrão em todas as falas. '+(saved?'Gravação salva neste navegador; será retomada ao reabrir.':'O navegador bloqueou o salvamento; prepare novamente ao reabrir.'))}catch(error){message('Não foi possível preparar a voz: '+error.message)}finally{busy=false;$('local-voice-prepare').disabled=false;$('local-voice-file').disabled=false}}
$('local-voice-prepare').onclick=()=>prepare($('local-voice-file').files[0]||remembered,true);
$('local-voice-test').onclick=()=>{audio.say('Oi, João! Seja bem-vindo!');message('Teste na fila com a voz do amigo. Ative o som para ouvir.')};
async function release(){audio.clear();audio.setLocalVoice(null);await runtime?.dispose();runtime=null;$('local-voice-test').disabled=true;$('local-voice-release').disabled=true}
$('local-voice-release').onclick=async()=>{await release();message('Voz pausada. Clique em Preparar voz gratuita para retomar a gravação salva.')};
$('local-voice-forget').onclick=async()=>{await release();try{await voiceReference('delete');remembered=null;$('local-voice-file').value='';$('local-voice-forget').disabled=true;message('Gravação removida deste navegador. Selecione o áudio para preparar a voz novamente.')}catch{message('Não foi possível remover a gravação salva.')}};
(async()=>{try{const saved=await voiceReference('read');if(saved?.file){remembered=saved.file;await prepare(remembered,false)}else message('Selecione a gravação do amigo uma vez para usar essa voz em todas as falas.')}catch{message('Selecione a gravação para preparar a voz. O armazenamento deste navegador está indisponível.')}})();
}
